/* Vulndesk Web: the same interface runs against the local adapter or sample fixtures. */
(() => {
  'use strict';
  const $ = (s, root=document) => root.querySelector(s);
  const esc = value => String(value ?? '').replace(/[&<>"']/g, c => ({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
  const fmt = value => new Intl.NumberFormat('id-ID').format(Number(value || 0));
  const date = value => value ? String(value).replace('T',' ').slice(0,16) : '—';
  const config = window.VULNDESK_CONFIG || {mode:'demo',local:false};
  const icons = {
    grid:'<rect x="3" y="3" width="7" height="7" rx="1.5"/><rect x="14" y="3" width="7" height="7" rx="1.5"/><rect x="3" y="14" width="7" height="7" rx="1.5"/><rect x="14" y="14" width="7" height="7" rx="1.5"/>',
    shield:'<path d="m12 3 8 3v6c0 5-8 9-8 9s-8-4-8-9V6z"/><path d="m8 12 3 3 5-6"/>',
    target:'<circle cx="12" cy="12" r="8"/><circle cx="12" cy="12" r="4"/><path d="m15 9 6-6M17 3h4v4"/>',
    layers:'<path d="m12 3 9 5-9 5-9-5zM3 12l9 5 9-5M3 16l9 5 9-5"/>',
    box:'<path d="m12 3 9 5v9l-9 5-9-5V8zM3 8l9 5 9-5M12 13v9M7 5.7l9 5"/>',
    chat:'<path d="M21 11a8 8 0 0 1-8 8H6l-4 3 1-6a8 8 0 1 1 18-5z"/><path d="M7 9h10M7 13h6"/>',
    cpu:'<rect x="6" y="6" width="12" height="12" rx="2"/><rect x="9" y="9" width="6" height="6" rx="1"/><path d="M9 2v4M15 2v4M9 18v4M15 18v4M2 9h4M2 15h4M18 9h4M18 15h4"/>',
    activity:'<path d="M2 12h4l3-8 6 16 3-8h4"/>',
    plug:'<path d="M9 2v5M15 2v5M6 7h12v3a6 6 0 0 1-12 0zM12 16v6"/>',
    refresh:'<path d="M20 8a8 8 0 0 0-14-3L3 8M3 3v5h5M4 16a8 8 0 0 0 14 3l3-3M16 16h5v5"/>',
    search:'<circle cx="10.5" cy="10.5" r="6.5"/><path d="m16 16 5 5"/>',
    download:'<path d="M12 3v12m-5-5 5 5 5-5M4 16v5h16v-5"/>',
    filter:'<path d="M3 4h18l-7 8v7l-4 2v-9z"/>',
    upload:'<path d="M12 16V3m-5 5 5-5 5 5M4 16v5h16v-5"/>',
    close:'<path d="m6 6 12 12M18 6 6 18"/>',
    menu:'<path d="M4 6h16M4 12h16M4 18h16"/>',
    clock:'<circle cx="12" cy="12" r="9"/><path d="M12 6v6l4 2"/>',
    play:'<path d="m8 4 12 8-12 8z"/>',
    stop:'<rect x="5" y="5" width="14" height="14" rx="2"/>',
    chevron:'<path d="m9 5 7 7-7 7"/>',
    trash:'<path d="M3 6h18M9 6V3h6v3M5 6l1 15h12l1-15M10 10v7M14 10v7"/>'
  };
  const icon = (name, size=18) => `<svg width="${size}" height="${size}" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.6" stroke-linecap="round" stroke-linejoin="round" aria-hidden="true">${icons[name] || icons.box}</svg>`;
  const pages = [ ['overview','Ringkasan','grid'],['vulnerabilities','Vulnerabilities','shield'],['attack','MITRE ATT&CK','target'],['cwe','CWE Catalog','layers'],['capec','CAPEC Catalog','target'],['cpe','CPE Dictionary','box'],['tweets','Tweet Topics','chat'],['sources','API Eksternal','plug'],['enrichment','CTI Enrichment','filter'],['components','CTI Components','cpu'],['missions','Mission Monitor','activity'] ];
  const samples = JSON.parse(JSON.stringify(window.VULNDESK_DEMO));
  const state = {mode:config.mode,view:'overview',tab:'',page:1,limit:10,search:'',sourceEnabled:'',sourceAdapter:'',severity:'',min:'',max:'',year:'',cwe:'',has_cpe:false,advanced:false,sort:'modified_at',direction:'desc',rows:[],total:0,missionId:'',missionTab:'status',enrichmentMission:'',enrichmentTab:'evidence',enrichmentDetail:null,loaded:null};
  let generation = 0, debounceTimer, catalogController;
  const isDemo = () => state.mode === 'demo';
  const statusBadge = (value, forced) => {
    const s = String(value || 'UNKNOWN').toUpperCase();
    const kind = forced || (/CRITICAL|FAILED|ERROR|OFFLINE|DENIED|DOWN|NOT_READY/.test(s)?'error':/HIGH|DEGRADED|WARNING|BLOCK|UNKNOWN/.test(s)?'warning':/MEDIUM/.test(s)?'medium':/READY|HEALTHY|ALLOW|COMPLETED|AVAILABLE|ACTIVE|OK/.test(s)?'ok':/LOW/.test(s)?'low':'muted');
    return `<span class="badge ${kind}">${esc(s)}</span>`;
  };
  function toast(message, error=false) {
    const el=document.createElement('div');el.className='toast'+(error?' error':'');el.textContent=message;$('#toast-region').append(el);setTimeout(()=>el.remove(),6500);
  }
  async function api(path, body, signal) {
    const response=await fetch('/api/'+path,{method:body===undefined?'GET':'POST',headers:body===undefined?{}:{'Content-Type':'application/json','X-Vulndesk-CSRF':config.csrf},body:body===undefined?undefined:JSON.stringify(body),cache:'no-store',signal:signal?AbortSignal.any([signal,AbortSignal.timeout(30000)]):AbortSignal.timeout(30000)});
    let result;try{result=await response.json();}catch{throw new Error('Respons server tidak valid.');}
    if(!response.ok)throw new Error(result.message || result.error || 'Layanan belum tersedia.');return result;
  }
  function currentDataset(){if(state.view==='attack')return state.tab || 'attack';if(state.view==='tweets')return state.tab || 'tweets';return state.view;}
  async function listData(dataset) {
    if(!isDemo()) {
      const q=new URLSearchParams({page:state.page,limit:state.limit,search:state.search,severity:state.severity,min:state.min,max:state.max,year:state.year,cwe:state.cwe,has_cpe:state.has_cpe?'1':'0',sort:state.sort,direction:state.direction});
      catalogController?.abort();catalogController=new AbortController();
      return api('data/'+dataset+'?'+q,undefined,catalogController.signal);
    }
    let rows=(samples[dataset]||[]).filter(r=>Object.entries(r).some(([k,v])=>k!=='raw_json'&&String(v).toLowerCase().includes(state.search.trim().toLowerCase())));
    if(dataset==='vulnerabilities') rows=rows.filter(r=>(!state.severity||r.preferred_base_severity===state.severity)&&(!state.min||r.preferred_base_score>=Number(state.min))&&(!state.max||r.preferred_base_score<=Number(state.max))&&(!state.year||String(r.cve_id).startsWith('CVE-'+state.year+'-'))&&(!state.cwe||(/^\d+$|^CWE-\d+$/i.test(state.cwe.trim())?String(r.cwe_id).toUpperCase()==='CWE-'+Number(state.cwe.trim().replace(/^CWE-/i,'')):String(r.cwe_id).toLowerCase().includes(state.cwe.trim().toLowerCase())))&&(!state.has_cpe||r.affected_product_count>0));
    const column=state.sort;
    rows.sort((a,b)=>{const av=a[column]??a.modified_at_source??a.id,bv=b[column]??b.modified_at_source??b.id;const order=typeof av==='number'?av-bv:String(av).localeCompare(String(bv));return state.direction==='asc'?order:-order;});
    const total=rows.length;return {items:rows.slice((state.page-1)*state.limit,state.page*state.limit),total,page:state.page,limit:state.limit};
  }
  async function summaryData() {
    if(!isDemo()) return api('summary');
    const severity={};samples.vulnerabilities.forEach(v=>severity[v.preferred_base_severity]=(severity[v.preferred_base_severity]||0)+1);
    return {counts:{vulnerabilities:samples.vulnerabilities.length,attack:samples.attack.length,cwe:samples.cwe.length,capec:(samples.capec||[]).length,cpe:samples.cpe.length,components:samples.components.length},severity,recent:samples.vulnerabilities.slice(0,5),sync:samples.sync,checked_at:new Date().toISOString(),database:{status:'SAMPLE'},services:demoServices()};
  }
  function demoServices(){return [['cti','CTI',8765],['gss','aptsGS',8770],['mission','Mission Orchestrator',8780],['pentest','Pentest Subsystem',8790]].map(([key,name,port])=>({key,name,port,status:'SIMULASI',readiness:'Belum diuji pada runtime',queue_depth:null,owned:false}));}
  function heading(title, description, actions=''){return `<div class="page-heading"><div><h1>${title}</h1><p>${description}</p></div><div class="heading-actions">${actions}</div></div>`;}
  function button(action,label,ico,primary=false,attrs=''){return `<button type="button" class="btn${primary?' primary':''}" data-action="${action}" ${attrs}>${ico?icon(ico,16):''}${label}</button>`;}
  const sourceUI=window.VulndeskSources.create({$,esc,icon,fmt,date,api,state,samples,isDemo,heading,button,stat,statusBadge,pagination,empty,openAction,toast,render});
  function stat(label,value,ico,description,color=''){return `<div class="stat-card"><div class="stat-top">${label}<span class="stat-icon ${color}">${icon(ico)}</span></div><div class="stat-value">${value==null?'—':fmt(value)}</div><div class="stat-description">${description}</div></div>`;}
  function serviceCards(services){return `<div class="service-grid">${services.map(s=>`<div class="service-card"><div class="service-card-top">${icon('activity',18)}${statusBadge(s.status,isDemo()?'purple':undefined)}</div><h3>${esc(s.name)}</h3><p>${esc(s.readiness || 'Status kesiapan belum tersedia')}</p><div class="service-bottom"><span class="mono">127.0.0.1:${Number(s.port)}</span><span>${s.queue_depth!=null?'Queue '+fmt(s.queue_depth):'HTTP health'}</span></div></div>`).join('')}</div>`;}
  const cveRows = rows => rows.map(r=>`<tr><td><button class="cve-link" data-detail="${r.id}" data-dataset="vulnerabilities">${esc(r.cve_id)}</button></td><td class="description-cell"><div class="table-title">${esc(r.product || r.description_text || 'Tanpa deskripsi')}</div>${r.product?`<small class="text-muted">${esc(r.description_text)}</small>`:''}</td><td>${statusBadge(r.preferred_base_severity)}</td><td class="score">${r.preferred_base_score==null?'—':Number(r.preferred_base_score).toFixed(1)}<small>CVSS ${esc(r.preferred_cvss_version||'—')}</small></td><td><span class="mono">${esc(r.cwe_id || (r.cwe_count?fmt(r.cwe_count)+' CWE':'—'))}</span></td><td>${r.attack_technique_count==null?'<span class="text-muted">Belum tersedia</span>':r.attack_technique_count?`<button class="cve-link" data-detail="${r.id}" data-dataset="vulnerabilities">${fmt(r.attack_technique_count)} teknik</button><small class="text-muted">${r.attack_mapping_status==='MAPPED_DIRECT'?'Langsung / konteks':r.attack_mapping_status==='MAPPED_VIA_CAPEC'?'Melalui CAPEC':'Melalui CWE'}</small>`:'<span class="text-muted">Belum ada aturan</span>'}</td><td class="date-cell">${date(r.modified_at)}</td><td><button class="row-menu" aria-label="Detail ${esc(r.cve_id)}" data-detail="${r.id}" data-dataset="vulnerabilities">${icon('chevron',16)}</button></td></tr>`).join('');
  const cveHead = sortable => `<thead><tr><th>${sortable?sortButton('cve_id','CVE ID'):'CVE ID'}</th><th>Deskripsi</th><th>Severity</th><th>${sortable?sortButton('preferred_base_score','CVSS'):'CVSS'}</th><th>CWE</th><th>ATT&amp;CK</th><th>${sortable?sortButton('modified_at','Diperbarui'):'Diperbarui'}</th><th><span class="sr-only">Detail</span></th></tr></thead>`;
  function sortButton(column,label){return `<button data-sort="${column}">${label}${state.sort===column?`<span class="sort-indicator">${state.direction==='desc'?'↓':'↑'}</span>`:''}</button>`;}
  function renderOverview(data) {
    const counts=data.counts, severity=data.severity, total=Math.max(1,counts.vulnerabilities);
    return heading('Intelligence overview','Pantau data kerentanan, sumber intelligence, dan kesiapan ekosistem CTI.',button('export-summary','Ekspor ringkasan','download')+button('sync','Sinkronisasi CTI','refresh',true))+
      (data.database?.status==='OFFLINE'?`<div class="error-state" style="margin-bottom:20px"><strong>Database belum tersambung.</strong> ${esc(data.database.message||'Periksa konfigurasi MariaDB.')} ${button('connection','Konfigurasi','plug')}</div>`:'')+
      `<div class="stats-grid">${stat('Total kerentanan',counts.vulnerabilities,'shield',isDemo()?'Entri contoh untuk pratinjau':'Tersimpan dalam database')}${stat('Critical & High',counts.vulnerabilities==null?null:(severity.CRITICAL||0)+(severity.HIGH||0),'activity','Prioritas berdasarkan skor CVSS','red')}${stat('Teknik ATT&CK',counts.attack,'target','Katalog teknik MITRE')}${stat('Komponen CTI',counts.components,'cpu','Agent, service & infrastruktur','green')}</div>`+
      `<div class="overview-grid"><section class="panel"><div class="panel-heading"><h2>Distribusi severity</h2><span class="sub">CVSS base severity</span></div><div class="panel-body">${['CRITICAL','HIGH','MEDIUM','LOW','UNKNOWN'].map((s,i)=>`<div class="severity-row"><span class="severity-name">${s==='UNKNOWN'?'Unknown':s[0]+s.slice(1).toLowerCase()}</span><div class="bar-track"><div class="bar-fill" style="width:${100*(severity[s]||0)/total}%;background:${['#d86c84','#e7a066','#e3cc76','#69ad99','#a3aec1'][i]}"></div></div><span class="severity-number">${fmt(severity[s])}</span></div>`).join('')}</div></section>
      <section class="panel"><div class="panel-heading"><h2>Katalog intelligence</h2><span class="sub">Data tersimpan</span></div><div class="panel-body">${[['NVD','Vulnerabilities',counts.vulnerabilities],['CWE','Weakness catalog',counts.cwe],['CAPEC','Attack pattern catalog',counts.capec],['CPE','Product dictionary',counts.cpe]].map(([symbol,label,n])=>`<div class="source-item"><span class="source-symbol">${symbol}</span><div class="grow"><span class="table-title">${label}</span><small>${isDemo()?'Data contoh':'Database lokal'}</small></div><div class="meta"><strong>${fmt(n)}</strong><small>entri</small></div></div>`).join('')}</div></section></div>`+
      `<div class="panel-heading" style="padding:0 0 14px;border:0"><h2>Koneksi subsistem</h2><button class="btn link" data-navigate="components">Lihat komponen</button></div>${serviceCards(data.services)}`+
      `<section class="panel"><div class="panel-heading"><h2>Kerentanan terbaru</h2><button class="btn link" data-navigate="vulnerabilities">Lihat semua</button></div><div class="table-wrap"><table>${cveHead(false)}<tbody>${cveRows(data.recent)}</tbody></table>${data.recent.length?'':empty('Belum ada data kerentanan','Sinkronkan sumber melalui CTI atau gunakan database yang sudah terisi.')}</div></section>`;
  }
  function empty(title,description){return `<div class="empty-state">${icon('search',24)}<strong>${title}</strong>${description}</div>`;}
  function pagination(){const pages=Math.max(1,Math.ceil(state.total/state.limit)),lo=Math.max(1,state.page-2),hi=Math.min(pages,lo+4);let nums='';for(let p=lo;p<=hi;p++)nums+=`<button class="page-button${p===state.page?' current':''}" data-page="${p}" ${p===state.page?'aria-current="page"':''}>${p}</button>`;return `<div class="pagination"><span>${state.total?fmt((state.page-1)*state.limit+1):0}–${fmt(Math.min(state.page*state.limit,state.total))} dari ${fmt(state.total)} entri</span><div class="page-buttons"><label for="page-size">Per halaman</label><select id="page-size" class="input" style="min-height:29px;padding:4px 22px 4px 8px;font-size:.75rem">${[10,25,50,100].map(n=>`<option ${n===state.limit?'selected':''}>${n}</option>`).join('')}</select><button class="page-button" data-page="${state.page-1}" aria-label="Halaman sebelumnya" ${state.page<=1?'disabled':''}>‹</button>${nums}<button class="page-button" data-page="${state.page+1}" aria-label="Halaman berikutnya" ${state.page>=pages?'disabled':''}>›</button></div></div>`;}
  function toolbar(extra=''){return `<div class="table-toolbar"><div class="toolbar-group"><div class="search-box">${icon('search',17)}<input id="search-input" class="input" type="search" value="${esc(state.search)}" placeholder="Cari ${state.view==='vulnerabilities'?'CVE ID atau deskripsi':'di katalog'}…" aria-label="Cari data"></div>${extra}</div><span class="metric-sub">${fmt(state.total)} entri</span></div>`;}
  function vulnerabilityFilters(){const years=Array.from({length:new Date().getFullYear()+2-1999},(_,i)=>new Date().getFullYear()+1-i);return `<label class="sr-only" for="filter-year">Tahun CVE</label><select id="filter-year" class="input" aria-label="Tahun CVE"><option value="">Semua tahun CVE</option>${years.map(y=>`<option value="${y}" ${String(y)===state.year?'selected':''}>${y}</option>`).join('')}</select><label class="sr-only" for="filter-cwe">CWE</label><input id="filter-cwe" class="input" aria-label="CWE" value="${esc(state.cwe)}" placeholder="CWE, mis. CWE-79" maxlength="40"><button class="btn" type="button" data-action="reset-filters">Reset</button>`;}
  function queueSearch(focusInput='search-input'){clearTimeout(debounceTimer);++generation;catalogController?.abort();$('#view').setAttribute('aria-busy','true');const metric=$('.table-toolbar .metric-sub');if(metric)metric.textContent='Mencari…';debounceTimer=setTimeout(()=>render({keep:true,focusSearch:true,focusInput}),300);}
  function advanced(){return `<form id="filter-form" class="advanced-filters"><div class="field narrow"><label for="score-min">CVSS minimum</label><input class="input" id="score-min" name="min" type="number" min="0" max="10" step="0.1" value="${esc(state.min)}" placeholder="0.0"></div><div class="field narrow"><label for="score-max">CVSS maksimum</label><input class="input" id="score-max" name="max" type="number" min="0" max="10" step="0.1" value="${esc(state.max)}" placeholder="10.0"></div><label class="checkbox-label"><input name="has_cpe" type="checkbox" ${state.has_cpe?'checked':''}>Memiliki CPE</label><button class="btn small primary" type="submit">Terapkan</button><button class="btn small" type="button" data-action="reset-filters">Reset</button></form>`;}
  function renderVulnerabilities(){return heading('Vulnerabilities','Telusuri CVE, nilai CVSS, kelemahan, dan produk yang terdampak.',button('export','Ekspor halaman','download')+button('sync','Sinkronisasi CTI','refresh',true))+`<section class="panel">${toolbar(`<select id="severity-filter" class="input" aria-label="Severity"><option value="">Semua severity</option>${['CRITICAL','HIGH','MEDIUM','LOW','UNKNOWN'].map(s=>`<option ${state.severity===s?'selected':''}>${s}</option>`).join('')}</select>${vulnerabilityFilters()}${button('advanced','Filter lanjutan','filter',false,'aria-expanded="'+state.advanced+'"')}`)}${state.advanced?advanced():''}<div class="table-wrap"><table>${cveHead(true)}<tbody>${cveRows(state.rows)}</tbody></table>${state.rows.length?'':empty('Tidak ada hasil','Ubah pencarian atau filter untuk menampilkan data.')}</div>${pagination()}</section>`;}
  const catalogs={attack:{title:'MITRE ATT&CK',description:'Teknik, perangkat lunak, dan aktor ancaman dalam satu katalog.',columns:[['attack_id','ATT&CK ID'],['name','Nama teknik'],['platforms_json','Platform'],['modified_at_source','Diperbarui']]},malware:{columns:[['software_id','Software ID'],['name','Nama malware'],['modified_at_source','Diperbarui']]},actors:{columns:[['group_id','Group ID'],['name','Threat actor'],['modified_at_source','Diperbarui']]},cwe:{title:'CWE Catalog',description:'Klasifikasi kelemahan perangkat lunak dari database CTI.',columns:[['cwe_id','CWE ID'],['cwe_name','Nama kelemahan'],['abstraction','Abstraction'],['likelihood_of_exploit','Likelihood'],['status_value','Status'],['cve_count','CVE terkait']]},capec:{title:'CAPEC Catalog',description:'Pola serangan CAPEC beserta relasi CWE dan MITRE ATT&CK dari database CTI.',columns:[['capec_id','CAPEC ID'],['name','Pola serangan'],['abstraction','Abstraction'],['status','Status'],['likelihood','Likelihood'],['severity','Severity'],['cwe_count','CWE terkait'],['attack_count','Teknik ATT&CK']]},cpe:{title:'CPE Dictionary',description:'Cari vendor, produk, dan versi dalam kamus CPE NVD.',columns:[['vendor','Vendor'],['product','Produk'],['version','Versi'],['cpe23_uri','CPE 2.3 URI'],['last_synced_at','Disinkronkan']]},tweets:{title:'Tweet Topics',description:'Kelola dataset tweet dan topik yang disimpan dalam CTI.',columns:[['tweet_text','Tweet'],['topic_text','Topik'],['file_name','Dataset'],['uploaded_at','Diunggah']]},topics:{columns:[['topic_text','Topik'],['file_name','Dataset'],['uploaded_at','Diunggah']]}};
  function tabs(items,active){return `<div class="tabs-row" role="tablist">${items.map(([key,label])=>`<button class="tab-button ${key===active?'active':''}" role="tab" aria-selected="${key===active}" data-tab="${key}">${label}</button>`).join('')}</div>`;}
  function catalogCell(key,value,row){if(key==='name'&&row?.capec_id&&!value)return '<small class="text-muted">Metadata pola belum tersedia</small>';if(key==='cwe_count'||key==='attack_count')return fmt(value);if(key==='cve_count')return Number(value)>0&&row&&row.cwe_id?`<button class="cve-link score" data-cwe-filter="${esc(row.cwe_id)}" title="Lihat CVE dengan ${esc(row.cwe_id)}">${fmt(value)}</button>`:`<span class="score">${fmt(value||0)}</span>`;if(key==='cwe_name'&&!value&&row&&row.cwe_id)return `<small class="text-muted">${String(row.cwe_id).startsWith('NVD-CWE')?'Placeholder NVD':'Belum disinkronkan'}</small>`;if(/json$/.test(key)){try{value=JSON.parse(value||'[]').join(', ');}catch{}}if(/_at/.test(key))return `<span class="date-cell">${date(value)}</span>`;if(/_id$/.test(key)||key==='cpe23_uri')return `<span class="mono">${esc(value||'—')}</span>`;return `<div class="${/name|product|topic_text/.test(key)?'table-title':''}">${esc(value||'—')}</div>`;}
  function renderCatalog(){const dataset=currentDataset(),spec=catalogs[dataset],parent=catalogs[state.view];const actions=state.view==='tweets'?button('export','Ekspor halaman','download')+button('upload','Impor CSV','upload',true):button('export','Ekspor halaman','download')+(state.view==='attack'||state.view==='cpe'?button('sync','Sinkronisasi CTI','refresh',true):'');return heading(parent.title,parent.description,actions)+`<section class="panel">${state.view==='attack'?tabs([['attack','Teknik'],['malware','Malware'],['actors','Threat actors']],dataset):state.view==='tweets'?tabs([['tweets','Tweet topics'],['topics','Topics master']],dataset):''}${toolbar(state.view==='tweets'?button('delete-dataset','Hapus dataset','trash'): '')}<div class="table-wrap"><table><thead><tr>${spec.columns.map(([key,label])=>`<th>${sortButton(key,label)}</th>`).join('')}<th>Detail</th></tr></thead><tbody>${state.rows.map(r=>`<tr>${spec.columns.map(([key])=>`<td ${/description|tweet_text|cpe23_uri/.test(key)?'class="description-cell"':''}>${catalogCell(key,r[key],r)}</td>`).join('')}<td><button class="row-menu" data-detail="${dataset==='capec'?esc(r.capec_id):r.id}" data-dataset="${dataset}" aria-label="Buka detail">${icon('chevron',16)}</button></td></tr>`).join('')}</tbody></table>${state.rows.length?'':empty('Tidak ada hasil','Coba kata kunci lain atau perbarui data.')}</div>${pagination()}</section>`;}
  function renderComponents(data){return heading('CTI Components','Kelola konfigurasi komponen dan periksa kesehatan API yang benar-benar berjalan.',button('diagnostics','Diagnostik CTI','activity'))+serviceCards(data.services)+`<section class="panel"><div class="runtime-control"><div><h2>Pentest Enrichment API</h2><p>Start / stop hanya berlaku untuk proses yang dijalankan oleh Web App ini.</p></div><div class="heading-actions">${button('start-api','Start API','play',true)}${button('stop-api','Stop API','stop',false,data.api_owned||isDemo()?'':'disabled title="Proses eksternal tidak dapat dihentikan"')}</div></div></section><section class="panel" style="margin-top:20px">${tabs([['registry','Registry'],['interfaces','Interfaces & ports']],state.tab||'registry')}${state.tab==='interfaces'?`<div class="panel-note">Alamat berikut berasal dari konfigurasi server lokal. Kesehatan layanan ditampilkan terpisah berdasarkan respons /health.</div><div class="table-wrap"><table><thead><tr><th>Modul</th><th>Endpoint lokal</th><th>Status terukur</th><th>Peran</th></tr></thead><tbody>${data.services.map(s=>`<tr><td class="table-title">${esc(s.name)}</td><td class="mono">http://127.0.0.1:${Number(s.port)}</td><td>${statusBadge(s.status,isDemo()?'purple':undefined)}</td><td>${esc({cti:'CTI enrichment & misi',gss:'Governance & authorization',mission:'Koordinasi misi lintas modul',pentest:'PIP ingress'}[s.key])}</td></tr>`).join('')}</tbody></table></div>`:`<div class="panel-note">Enabled adalah konfigurasi registry. Nilai ini tidak membuktikan bahwa agent sedang mengeksekusi task.</div><div class="table-wrap"><table><thead><tr><th>ID</th><th>Komponen</th><th>Tipe / mekanisme</th><th>Status registry</th><th>Enabled</th><th>Detail</th></tr></thead><tbody>${data.items.map(r=>`<tr><td class="mono">${esc(r.component_id)}</td><td><span class="table-title">${esc(r.service_name)}</span><small class="text-muted">${esc(r.authority_boundary)}</small></td><td>${esc(r.component_type)}<small class="text-muted">${esc(r.mechanism)}</small></td><td>${statusBadge(r.status)}${r.last_error?'<small class="danger-text">Ada error; buka detail</small>':''}</td><td><label class="checkbox-label"><input type="checkbox" data-toggle="${esc(r.service_key)}" aria-label="Aktifkan ${esc(r.service_name)}" ${r.enabled?'checked':''} ${r.component_type==='Data Artifact'?'disabled':''}><span>${r.enabled?'On':'Off'}</span></label></td><td><button class="row-menu" data-detail="${r.id}" data-dataset="components" aria-label="Detail komponen">${icon('chevron',16)}</button></td></tr>`).join('')}</tbody></table>${data.items.length?'':empty('Registry belum tersedia','Periksa koneksi database dan skema CTI.')}</div>`}</section>`;}
  async function enrichmentData(){
    if(isDemo()) return {items:[],total:0,page:1,limit:25};
    const q=new URLSearchParams({page:state.page,limit:state.limit,search:state.search,mission_id:state.enrichmentMission||'',sort:'created_at',direction:state.direction});
    return api('enrichment?'+q);
  }
  async function enrichmentDetail(intakeId){
    if(isDemo()) return null;
    return api('enrichment/'+encodeURIComponent(intakeId));
  }
  function renderEnrichment(data){
    const enrichmentTabs=[['evidence','Evidence'],['technologies','Technologies'],['cpe_candidates','CPE Candidates'],['pipeline','Pipeline Status']];
    const activeTab=state.enrichmentTab||'evidence';
    return heading('CTI Enrichment','Data enrichment hasil observasi (fingerprinting) dari Recon Agent melalui HMAC-authenticated delivery.',button('refresh','Refresh','refresh'))+
      `<section class="panel"><div class="table-toolbar"><div class="toolbar-group"><div class="search-box">${icon('search',17)}<input id="search-input" class="input" type="search" value="${esc(state.search)}" placeholder="Cari URL target, intake, mission, task…" aria-label="Cari evidence"></div><div class="search-box" style="max-width:260px"><label class="sr-only" for="enrichment-mission">Mission</label><input id="enrichment-mission" class="input mono" type="text" value="${esc(state.enrichmentMission||'')}" placeholder="Filter by mission_id…"></div></div><span class="metric-sub">${fmt(data.total)} evidence</span></div>`+
      `<div class="table-wrap"><table class="enrichment-table"><thead><tr><th>Target URL / Evidence</th><th>Mission / Task</th><th>Technologies</th><th>CPE</th><th>Classification</th><th>${sortButton('created_at','Created')}</th><th><span class="sr-only">Detail</span></th></tr></thead><tbody>${data.items.map(r=>`<tr><td><strong class="enrichment-target">${esc(r.target?.target_value||'URL target belum tersimpan')}</strong><button class="cve-link enrichment-id" title="${esc(r.intake_id)}" data-enrichment-detail="${esc(r.intake_id)}">${esc(r.intake_id)}</button></td><td><span class="mono enrichment-id" title="${esc(r.mission_id)}">${esc(r.mission_id)}</span><small class="mono enrichment-id" title="${esc(r.task_id)}">${esc(r.task_id)}</small></td><td>${fmt(r.technology_count)}<small class="text-muted">${esc((r.technologies||[]).map(t=>[t.name,t.version].filter(Boolean).join(' ')).join(', ')||'Daftar belum tersimpan')}</small></td><td>${fmt(r.cpe_candidate_count)}</td><td><span title="${esc(r.classification)}">${statusBadge(r.classification==='CTI_CONTEXT_ENRICHMENT_NOT_CONFIRMED_VULNERABILITIES'?'Konteks · belum terkonfirmasi':r.classification||'UNKNOWN')}</span>${r.enrichment_version<2?'<small class="text-muted">Hasil lama · perlu diproses ulang</small>':''}</td><td class="date-cell">${date(r.created_at)}</td><td><button class="row-menu" data-enrichment-detail="${esc(r.intake_id)}" aria-label="Detail ${esc(r.intake_id)}">${icon('chevron',16)}</button></td></tr>`).join('')}</tbody></table>${data.items.length?'':empty('Belum ada evidence','Evidence akan muncul setelah pipeline fingerprinting → HMAC delivery → CTI enrichment dijalankan.')}</div>${pagination()}</section>`+
      `<section class="panel" style="margin-top:16px" id="enrichment-detail-section">${state.enrichmentDetail?renderEnrichmentDetail(state.enrichmentDetail,activeTab,enrichmentTabs):`<div class="empty-state">${icon('filter',24)}<strong>Pilih evidence</strong>Klik baris di atas untuk melihat detail enrichment.</div>`}</section>`;
  }
  function renderTechnologyResolution(d){
    const resolutions=d.technology_resolution||d.result?.technology_resolution||[];
    const labels={PRODUCT_NOT_FOUND:'Produk belum tersedia di dictionary lokal',VERSION_NOT_FOUND:'Produk dikenali; versi belum ditemukan',VERSION_UNKNOWN:'Produk dikenali; versi target belum diketahui',EXACT_VERSION_MATCH:'Produk dan versi cocok dengan dictionary'};
    if(!resolutions.length)return '';
    return `<div class="section-label">Hasil resolusi per teknologi</div><div class="detail-grid">${resolutions.map(t=>`<div><small>${esc(t.name)} ${esc(t.version||'· versi belum diketahui')}</small><strong>${esc(labels[t.status]||t.status)}</strong><small class="mono">${esc(t.status)}</small></div>`).join('')}</div>`;
  }
  function renderEnrichmentDetail(d,activeTab,enrichmentTabs){
    const r=d.result||{};const techs=d.technologies||r.technologies||[];const cpes=d.cpe_candidates||r.cpe_candidates||[];
    let body='';
    if(activeTab==='evidence'){
      body=`<div class="panel-note"><strong>Target URL</strong><div class="enrichment-target">${esc(d.target?.target_value||'Belum tersimpan pada evidence lama')}</div></div><div class="detail-grid"><div><small>Intake ID</small><strong class="mono">${esc(d.intake_id)}</strong></div><div><small>Mission ID</small><strong class="mono">${esc(d.mission_id)}</strong></div><div><small>Task ID</small><strong class="mono">${esc(d.task_id)}</strong></div><div><small>Recon Run</small><strong class="mono">${esc(d.recon_run_id)}</strong></div><div><small>Input SHA-256</small><strong class="mono">${esc(d.input_sha256)}</strong></div><div><small>Manifest SHA-256</small><strong class="mono">${esc(d.evidence_manifest_sha256)}</strong></div><div><small>Created</small><strong>${date(d.created_at)}</strong></div><div><small>Classification</small><strong>${d.classification?statusBadge(d.classification):'—'}</strong></div></div><div class="section-label">Enrichment Summary</div><div class="detail-grid"><div><small>Technologies</small><strong>${fmt(d.technology_count)}</strong></div><div><small>CPE Candidates</small><strong>${fmt(d.cpe_candidate_count)}</strong></div><div><small>Verified Vulns</small><strong>${fmt(d.verified_vulnerability_count||r.verified_vulnerability_count||0)}</strong></div><div><small>Target I/O by CTI</small><strong>${(d.target_io_performed_by_cti||r.target_io_performed_by_cti)?'Yes':'No'}</strong></div></div>`;
    } else if(activeTab==='technologies'){
      body=renderTechnologyResolution(d)+`<div class="table-wrap"><table><thead><tr><th>Technology</th><th>Version</th></tr></thead><tbody>${techs.map(t=>`<tr><td class="table-title">${esc(t.name||t.technology_name||'—')}</td><td>${esc(t.version||t.technology_version||'—')}</td></tr>`).join('')}</tbody></table>${techs.length?'':empty('Daftar teknologi tidak tersedia',d.technology_count?'Evidence lama hanya menyimpan jumlah teknologi; proses ulang dari evidence sumber diperlukan.':'Tidak ada teknologi teramati pada evidence ini.')}</div>`;
    } else if(activeTab==='cpe_candidates'){
      body=renderTechnologyResolution(d)+`<div class="panel-note">Kandidat produk tidak menetapkan versi target. URI referensi hanya membuktikan identitas produk di dictionary; kandidat tetap memerlukan verifikasi.</div><div class="table-wrap"><table><thead><tr><th>Technology</th><th>Versi teramati</th><th>Produk / CPE</th><th>Skor pencocokan</th><th>Alasan</th><th>Status</th><th>Exploitable</th></tr></thead><tbody>${cpes.map(c=>`<tr><td>${esc(c.technology_name||'—')}</td><td>${esc(c.technology_version||'—')}</td><td><strong>${esc([c.vendor,c.product].filter(Boolean).join(' / ')||'—')}</strong><small>${esc(c.match_level==='PRODUCT'?'Kandidat identitas produk':'Kecocokan versi')}</small><div class="mono enrichment-target">${esc(c.cpe23_uri||'CPE versi target belum ditentukan')}</div>${c.reference_cpe23_uri?`<small>Referensi dictionary · bukan versi target</small><div class="mono enrichment-target">${esc(c.reference_cpe23_uri)}</div>`:''}</td><td>${c.match_confidence!=null?Number(c.match_confidence).toFixed(2):'—'}</td><td>${esc(c.reason||'Alasan belum tersimpan')}<small>${esc(c.match_method||'')}</small></td><td>${c.status?statusBadge(c.status):'—'}</td><td>${c.exploitability_confirmed?'Yes':'No'}</td></tr>`).join('')}</tbody></table>${cpes.length?'':empty('Tidak ada CPE candidates',d.pipeline_status?.cpe_resolution==='COMPLETED_NO_MATCH'?'Lihat alasan setiap teknologi di atas; data dictionary atau versi observasi mungkin belum lengkap.':'Evidence ini belum memiliki CPE candidate.')}</div>`;
    } else {
      const pipeline=d.pipeline_status||{};
      const labels={QUEUED:'Menunggu antrean',PENDING:'Menunggu antrean',RUNNING:'Sedang diproses',COMPLETED:'Selesai',FAILED:'Gagal diproses',NOT_COMPLETED:'Tahap belum selesai',SEALED:'SEALED',COMPLETED_WITH_CANDIDATES:'Selesai · kandidat perlu verifikasi',COMPLETED_NO_MATCH:'Selesai · tidak ada kecocokan',NOT_RUN:'Belum dijalankan',NOT_RECORDED:'Belum tercatat untuk misi ini',RECORDED_FOR_MISSION:'Ada hasil tingkat misi',ASSEMBLED_WITH_EVIDENCE:'Sudah dirakit · memuat evidence ini',ASSEMBLED_WITHOUT_EVIDENCE:'Sudah dirakit · belum memuat evidence ini',UNKNOWN:'Tidak tersedia'};
      const info=d.pipeline_details||{};
      const sub=key=>{const x=info[key]||{};
        if(x.intake_record_count!=null)return `${fmt(x.intake_record_count)} rekaman untuk intake ini`;
        if(pipeline[key]==='RECORDED_FOR_MISSION')return `${fmt(x.mission_record_count)} rekaman untuk misi (tidak terikat ke intake ini)`;
        if(key==='pip_assembly'&&x.latest_revision!=null)return `Revisi terbaru ${x.latest_revision} · ${x.latest_readiness||'—'} · ${x.revision_count} revisi`+(pipeline[key]==='ASSEMBLED_WITHOUT_EVIDENCE'?' · tidak ada yang merujuk intake/manifest ini':'');
        return '';};
      const jobNote=d.pipeline?`<p class="panel-note">Pipeline intake: ${esc(d.pipeline.status)} · Misi CTI ${esc(d.pipeline.pipeline_mission_id||'belum dibuat')} · Percobaan ${fmt(d.pipeline.attempt_count||0)}</p>`:'';
      const stages=[['cpe_resolution','CPE Resolution'],['vulnerability_correlation','Vulnerability Correlation'],['attack_mapping','ATT&CK Mapping'],['risk_prioritization','Risk Prioritization'],['pip_assembly','PIP Assembly']];
      body=jobNote+`<div class="runtime-bands"><span>Evidence status</span>${statusBadge(d.evidence_status||'UNKNOWN')}</div><div class="detail-grid" style="margin-top:12px">${stages.map(([key,label])=>`<div><small>${esc(label)}</small><strong>${esc(labels[pipeline[key]]||pipeline[key]||'Tidak tersedia')}</strong>${sub(key)?`<small>${esc(sub(key))}</small>`:''}</div>`).join('')}</div><div class="panel-note">Status berasal dari hasil backend; tahap setelah CPE dihitung dari tabel masing-masing, bukan dari snapshot saat evidence masuk. Jumlah kerentanan nol tidak menyatakan korelasi sudah dijalankan. Skor CPE adalah heuristik, bukan probabilitas kerentanan.</div>`;
    }
    return `<div class="panel-heading"><h2>${esc(d.intake_id)}</h2><span class="sub">${esc(d.mission_id)} · ${date(d.created_at)}</span></div>${tabs(enrichmentTabs,activeTab)}${body}`;
  }
  function renderMissions(data){return heading('Mission Monitor','Periksa status, event, diagnostik, dan lineage misi dari runtime CTI.',button('sync','Misi akuisisi CTI','play',true))+`<section class="panel"><form id="mission-form" class="trace-header"><label class="sr-only" for="mission-id">Mission ID</label><input id="mission-id" class="input mono" placeholder="Masukkan Mission ID" value="${esc(state.missionId)}" required maxlength="160"><button class="btn primary" type="submit">Tampilkan misi</button></form>${tabs([['status','Status'],['events','Event trace'],['diagnostics','Diagnostics'],['lineage','Lineage'],['integrity','Integrity']],state.missionTab)}${!data?empty('Cari misi CTI','Gunakan Mission ID dari Mission Orchestrator atau misi akuisisi CTI.'):state.missionTab==='events'?renderTimeline(data):`<div class="panel-body"><div class="runtime-bands"><span class="mono">${esc(state.missionId)}</span>${statusBadge((state.missionTab==='status'?data.status:null)||data.runtime_status||data.verification_status||data.validation_status||data.readiness_status||(isDemo()?'SAMPLE':'DATA TERSEDIA'),isDemo()?'purple':undefined)}</div><pre class="detail-json">${esc(JSON.stringify(data,null,2))}</pre></div>`}</section>`;}
  function renderTimeline(data){let events=Array.isArray(data)?data:(data.events||data.items||[]);if(!events.length)return empty('Belum ada event','Runtime belum mengembalikan event untuk misi ini.');return `<div class="timeline">${events.map(e=>`<div class="timeline-item"><h3>${esc(e.event_type||e.type||'Event')}</h3><code>${esc(e.event_id||e.id||'')} · ${date(e.timestamp||e.created_at||e.occurred_at)}</code><p>${esc(e.summary||e.source_component||e.reason_code||'')}</p><details><summary class="metric-sub">Payload</summary><pre class="detail-json">${esc(JSON.stringify(e,null,2))}</pre></details></div>`).join('')}</div>`;}
  function sampleMission(){if(state.missionTab==='events')return {sample:true,events:[{event_id:'event-demo-01',event_type:'MissionReceived',timestamp:'2026-10-05T09:00:00',summary:'Contoh penerimaan misi CTI'},{event_id:'event-demo-02',event_type:'TaskProposed',timestamp:'2026-10-05T09:00:01',summary:'Contoh proposal akuisisi; tidak dikirim ke GSS'},{event_id:'event-demo-03',event_type:'AwaitingAuthorization',timestamp:'2026-10-05T09:00:02',summary:'Simulasi berhenti sebelum tindakan operasional'}]};return {sample:true,mission_id:state.missionId,status:'SAMPLE',view:state.missionTab,notice:'Data contoh. Tidak ada misi atau keputusan GSS yang dijalankan.',plan_version:1,state_version:1,execution_authorized:false};}
  function updateMode(){const demo=isDemo();$('#mode-badge').textContent=demo?'DATA CONTOH':'LOKAL · DATA AKTUAL';$('#mode-badge').className='badge '+(demo?'demo':'live');$('#mode-note').className='mode-note'+(demo?'':' live');$('#mode-note').innerHTML=demo?`<span><strong>Mode pratinjau.</strong> Seluruh data adalah contoh. Status modul dan tindakan ditampilkan sebagai simulasi.</span><button data-action="connection">Tentang koneksi lokal</button>`:`<span><strong>Mode lokal.</strong> Data diambil dari database dan API CTI pada komputer ini.</span><button data-action="connection">Pengaturan koneksi</button>`;}
  async function render(options={}) {
    const ticket=++generation;const focusId=options.focusInput||'search-input',searchFocused=document.activeElement?.id===focusId;updateMode();$('#view').setAttribute('aria-busy','true');$('#navigation').innerHTML=pages.map(([id,title,ico])=>`<a class="nav-item ${state.view===id?'active':''}" href="#${id}" ${state.view===id?'aria-current="page"':''}>${icon(ico)}<span>${title}</span></a>`).join('');$('#breadcrumb-current').textContent=pages.find(p=>p[0]===state.view)[1];
    if(!options.keep){$('#view').innerHTML='<div class="panel panel-body"><div class="skeleton" style="width:40%"></div><div class="skeleton"></div><div class="skeleton"></div></div>';}
    try {
      let html,data;
      if(state.view==='overview'){data=await summaryData();html=renderOverview(data);}
      else if(state.view==='components'){data=isDemo()?{items:samples.components,services:demoServices(),api_owned:false}:await api('components');html=renderComponents(data);}
      else if(state.view==='sources'){data=await sourceUI.load();if(ticket!==generation)return;state.page=data.page;state.rows=data.items;state.total=data.total;html=sourceUI.pageHTML(data);}
      else if(state.view==='enrichment'){data=await enrichmentData();if(ticket!==generation)return;state.rows=data.items;state.total=data.total;html=renderEnrichment(data);}
      else if(state.view==='missions'){data=state.missionId?(isDemo()?sampleMission():await api('missions/'+encodeURIComponent(state.missionId)+'/'+state.missionTab)):null;html=renderMissions(data);}
      else{data=await listData(currentDataset());if(ticket!==generation)return;state.rows=data.items;state.total=data.total;html=state.view==='vulnerabilities'?renderVulnerabilities():renderCatalog();}
      if(ticket!==generation)return;if(['overview','components','missions'].includes(state.view)){state.rows=[];state.total=0;}if(state.view!=='enrichment')state.enrichmentDetail=null;state.loaded=data;$('#view').innerHTML=html;$('#updated-label').textContent='Diperbarui '+new Date().toLocaleTimeString('id-ID',{hour:'2-digit',minute:'2-digit'});
      $('#view').setAttribute('aria-busy','false');
      if(options.focusSearch&&searchFocused&&(!document.activeElement?.id||document.activeElement.id===focusId)){const el=$('#'+focusId);if(el){el.focus();el.setSelectionRange?.(el.value.length,el.value.length);}}
    }catch(error){if(ticket!==generation)return;$('#view').setAttribute('aria-busy','false');state.rows=[];state.total=0;state.loaded=null;$('#view').innerHTML=(state.view==='missions'?renderMissions(null):heading(pages.find(p=>p[0]===state.view)[1],'Data belum dapat dimuat.'))+`<div class="error-state" style="margin-top:20px"><strong>Data belum tersedia</strong><p>${esc(error.message)}</p><div class="heading-actions" style="margin-top:15px">${button('refresh','Coba lagi','refresh')}${button('connection','Periksa konfigurasi','plug')}</div></div>`;}
  }
  function navigate(view){if(!pages.some(p=>p[0]===view))throw new Error('Halaman tidak dikenal.');if(location.hash==='#'+view){return render();}location.hash=view;}
  let pendingCwe='';
  function onRoute(){clearTimeout(debounceTimer);catalogController?.abort();state.view=pages.some(p=>p[0]===location.hash.slice(1))?location.hash.slice(1):'overview';state.tab='';state.page=1;state.search='';state.sourceEnabled='';state.sourceAdapter='';state.severity='';state.min='';state.max='';state.year='';state.cwe='';state.has_cpe=false;state.advanced=false;if(pendingCwe&&state.view==='vulnerabilities'){state.cwe=pendingCwe;state.advanced=true;}pendingCwe='';state.sort=state.view==='vulnerabilities'?'modified_at':state.view==='enrichment'?'created_at':state.view==='cwe'?'cwe_id':state.view==='capec'?'capec_id':'id';state.direction=['cwe','capec'].includes(state.view)?'asc':'desc';state.enrichmentMission='';state.enrichmentTab='evidence';state.enrichmentDetail=null;$('#sidebar').classList.remove('open');return render();}
  function openAction(title,description,body){$('#action-content').innerHTML=`<div class="dialog-header"><div><h2>${title}</h2><p>${description}</p></div><button class="icon-button" data-close="action-dialog" aria-label="Tutup">${icon('close')}</button></div>${body}`;$('#action-dialog').showModal();}
  function cweAttackHTML(row){
    const mappings=row.attack_mappings||[];
    const confidence=value=>value==null?'Tidak tersedia':`${(Number(value)*100).toFixed(1)}%`;
    const relationships={exploitation_technique:'Metode eksploitasi',primary_impact:'Dampak utama',secondary_impact:'Dampak lanjutan',uncategorized:'Belum dikategorikan',taxonomy_mapping:'Relasi taksonomi CAPEC'};
    let body;
    if(row.attack_mapping_status==null){body='<p class="text-muted">Pemetaan ATT&amp;CK belum tersedia untuk data ini.</p>';}
    else if(!mappings.length){body='<p class="text-muted">Belum ada aturan ATT&amp;CK aktif yang cocok dengan CVE atau CWE ini. Ini bukan bukti bahwa CVE tidak berkaitan dengan teknik serangan.</p>';}
    else{body='<p class="inline-note">Relasi langsung terkurasi ditandai CURATED; pemetaan tidak langsung melalui CWE/CAPEC ditandai INFERRED. Confidence impor adalah baseline kebijakan APTS, bukan skor dari penerbit. Hasil ini bukan bukti eksploitasi atau kerentanan terkonfirmasi pada target.</p>'+mappings.map(m=>`<section><h3><button type="button" class="cve-link" data-attack-relations="${esc(m.attack_id)}">${esc(m.attack_id)} · ${esc(m.technique_name||'Nama teknik belum tersedia')}</button> · ${esc(m.mapping_status||'INFERRED')}</h3><p>Confidence aturan terkuat: <strong>${confidence(m.confidence)}</strong></p>${(m.paths||[]).map(p=>{
      const route=[row.cve_id,p.cwe_id,p.capec_id,m.attack_id].filter(Boolean).map(esc).join(' → ');
      const references=(()=>{try{return JSON.parse(p.references_json||'[]');}catch{return [];}})();
      const links=[p.source_url,...(Array.isArray(references)?references:[])].filter(u=>typeof u==='string'&&/^https?:\/\//i.test(u));
      return `<div class="panel-body"><p class="mono">${route}</p><p>${esc(p.cwe_name||'')} · ${esc(p.tactic_name||'Taktik belum tersedia')} · ${esc(relationships[p.relationship_type]||p.relationship_type||'Konteks CWE')}</p><p>Sumber: <strong>${esc(p.source_dataset||p.mapping_source||'Tidak tersedia')}</strong> · Aturan ${esc(p.rule_id)} · Confidence ${confidence(p.confidence)}</p><p>${esc(p.rationale||'Alasan pemetaan belum tersedia.')}</p>${p.source_version?`<p>Versi ${esc(p.source_version)} · Status penerbit ${esc(p.publisher_status||'—')}</p><p class="mono">SHA-256: ${esc(p.source_sha256||'—')}</p>`:''}${links.map(u=>`<p><a href="${esc(u)}" target="_blank" rel="noopener noreferrer">${esc(u)}</a></p>`).join('')}</div>`;
    }).join('')}</section>`).join('');}
    return '<div class="section-label">Konteks ATT&amp;CK — langsung / CWE / CAPEC</div>'+body;
  }
  function attackRelationsHTML(data){
    if(!data)return '<p class="text-muted">Relasi CVE belum tersedia untuk data ini.</p>';
    const attackId=data.attack_id||data.technique?.attack_id||'';
    const labels={ALL:'Semua jalur',DIRECT_CVE:'Langsung dari CVE',CWE_RULE:'Melalui CWE',CAPEC:'Melalui CWE / CAPEC'};
    const page=data.page||1,limit=data.limit||10,total=data.total||0,pages=Math.max(1,Math.ceil(total/limit));
    const pageButton=(number,label,disabled)=>`<button type="button" class="btn" data-attack-relations="${esc(attackId)}" data-attack-page="${number}" data-attack-limit="${limit}" data-attack-kind="${esc(data.mapping_kind||'ALL')}" data-attack-search="${esc(data.search||'')}" ${disabled?'disabled':''}>${label}</button>`;
    return `<div class="section-label">CVE terkait · ${fmt(total)} CVE unik</div><p class="inline-note">Relasi katalog menggambarkan konteks teknik; setiap jalur menyimpan sumber dan alasan pemetaan. Relasi ini bukan bukti eksploitasi pada target.</p>${data.technique?.deprecated||data.technique?.revoked?'<p class="inline-note">Teknik ini deprecated atau revoked pada katalog lokal; relasi historis tetap ditampilkan bersama versi sumber.</p>':''}
      <form id="attack-relations-form" class="attack-relations-form"><input type="hidden" name="attack_id" value="${esc(attackId)}"><div class="field"><label for="attack-related-search">Cari CVE ID</label><input id="attack-related-search" class="input" name="search" value="${esc(data.search||'')}" maxlength="100" placeholder="CVE-2024-…"></div><div class="field"><label for="attack-related-kind">Jalur pemetaan</label><select id="attack-related-kind" class="input" name="mapping_kind">${Object.entries(labels).map(([key,label])=>`<option value="${key}" ${key===(data.mapping_kind||'ALL')?'selected':''}>${label}</option>`).join('')}</select></div><div class="field"><label for="attack-related-limit">CVE per halaman</label><select id="attack-related-limit" name="limit" class="input">${[10,25,50].map(n=>`<option ${n===limit?'selected':''}>${n}</option>`).join('')}</select></div><button type="submit" class="btn primary">Terapkan</button></form>
      ${data.items?.length?`<div class="table-wrap"><table class="attack-relations-table"><thead><tr><th>CVE</th><th>Severity / CVSS</th><th>Status</th><th>Sumber / jalur</th></tr></thead><tbody>${data.items.map(row=>{
        const mapping=row.mapping||{},paths=mapping.paths||[],sources=[...new Set(paths.map(p=>p.source_dataset||p.mapping_source||'Tidak tersedia'))];
        return `<tr><td class="description-cell"><button type="button" class="cve-link" data-detail="${esc(row.id)}" data-dataset="vulnerabilities">${esc(row.cve_id)}</button><small class="text-muted">${esc((row.description_text||'').slice(0,240))}</small></td><td>${statusBadge(row.preferred_base_severity)}<small>CVSS ${row.preferred_base_score==null?'—':Number(row.preferred_base_score).toFixed(1)}</small></td><td>${esc(mapping.mapping_status||'INFERRED')}</td><td>${esc(sources.join(', '))}<details><summary>Lihat ${fmt(paths.length)} jalur dan evidence</summary>${cweAttackHTML({...row,attack_mapping_status:'MAPPED',attack_mappings:[mapping]})}</details></td></tr>`;
      }).join('')}</tbody></table></div>`:'<p class="text-muted">Tidak ada relasi yang cocok dengan filter ini. Ini bukan bukti bahwa teknik tidak berkaitan dengan CVE.</p>'}
      <div class="form-actions">${pageButton(page-1,'Sebelumnya',page<=1)}<span>Halaman ${fmt(page)} / ${fmt(pages)}</span>${pageButton(page+1,'Berikutnya',page>=pages)}</div>`;
  }
  function capecDetailsHTML(row){
    const metadata=[['Abstraction',row.abstraction],['Status',row.status],['Likelihood',row.likelihood],['Severity',row.severity]];
    const provenance=m=>`<small class="text-muted">${esc([m.source_dataset,m.source_version,m.relationship_type].filter(Boolean).join(' · ')||'Provenance belum tersedia')}</small>`;
    return `${!row.name?'<p class="inline-note">CAPEC ini tersedia dari tabel relasi. Metadata pola belum tersedia di capec_patterns.</p>':''}<p>${esc(row.description||'Deskripsi belum tersedia.')}</p><div class="detail-grid">${metadata.map(([label,value])=>`<div><small>${label}</small><strong>${esc(value||'—')}</strong></div>`).join('')}</div>`+
      [['Prasyarat',row.prerequisites],['Mitigasi',row.mitigations]].map(([label,value])=>`<div class="section-label">${label}</div><pre class="detail-json">${esc(value||'Belum tersedia')}</pre>`).join('')+
      `<div class="section-label">CWE terkait</div>${(row.cwe_mappings||[]).map(m=>`<p><button class="cve-link" data-cwe-filter="${esc(m.cwe_id)}">${esc(m.cwe_id)}</button> · ${esc(m.cwe_name||'Nama kelemahan belum tersedia')}${provenance(m)}</p>`).join('')||'<p class="text-muted">Belum ada pemetaan CWE aktif.</p>'}`+
      `<div class="section-label">MITRE ATT&CK terkait</div><p class="inline-note">Relasi taksonomi CAPEC adalah konteks INFERRED, bukan bukti eksploitasi pada target.</p>${(row.attack_mappings||[]).map(m=>`<p><button class="cve-link" data-attack-relations="${esc(m.attack_id)}">${esc(m.attack_id)}</button> · ${esc(m.attack_name||'Nama teknik belum tersedia')}${provenance(m)}<small>${esc(m.rationale||'')}</small></p>`).join('')||'<p class="text-muted">Belum ada pemetaan ATT&CK aktif.</p>'}`;
  }
  function detailsHTML(dataset,row){const title=row.cve_id||row.attack_id||row.capec_id||row.cwe_id||row.software_id||row.group_id||row.service_name||row.title||row.topic_text||'Detail data';const safeURL=u=>{try{const p=new URL(u);return ['https:','http:'].includes(p.protocol)?p.href:'';}catch{return '';}};let sections='';if(dataset==='vulnerabilities'){sections=`<div class="detail-summary">${statusBadge(row.preferred_base_severity)}<strong>CVSS ${row.preferred_base_score==null?'—':Number(row.preferred_base_score).toFixed(1)}</strong><span class="text-muted">v${esc(row.preferred_cvss_version||'—')}</span></div><p>${esc(row.description_text||'Tanpa deskripsi')}</p><div class="section-label">Metadata</div><div class="detail-grid"><div><small>Publikasi</small><strong>${date(row.published_at)}</strong></div><div><small>Diperbarui</small><strong>${date(row.modified_at)}</strong></div><div><small>Status</small><strong>${esc(row.vuln_status||'—')}</strong></div><div><small>Vector</small><strong class="mono">${esc(row.preferred_vector_string||'—')}</strong></div></div><div class="section-label">CWE</div><pre class="detail-json">${esc(JSON.stringify(row.cwes||[{cwe_id:row.cwe_id}],null,2))}</pre>${cweAttackHTML(row)}<div class="section-label">Produk / CPE</div><pre class="detail-json">${esc(JSON.stringify(row.cpe_matches||[],null,2))}</pre><div class="section-label">Referensi</div>${(row.references||[]).map(ref=>{const url=safeURL(ref.url);return url?`<p><a href="${esc(url)}" target="_blank" rel="noopener noreferrer">${esc(ref.url)}</a></p>`:'';}).join('')||'<p class="text-muted">Tidak ada referensi dalam data ini.</p>'}`;}else if(dataset==='capec'){sections=capecDetailsHTML(row);}else if(dataset==='attack'){sections=`<p>${esc(row.description_text||'Deskripsi teknik belum tersedia.')}</p>${attackRelationsHTML(row.related_vulnerabilities)}`;}else{sections=`<p>${esc(row.description_text||row.tweet_text||row.authority_boundary||'')}</p><div class="section-label">Informasi</div><pre class="detail-json">${esc(JSON.stringify(Object.fromEntries(Object.entries(row).filter(([k])=>k!=='raw_json')),null,2))}</pre>`;}return `<div class="dialog-header"><div><h2>${esc(title)}</h2><p>${esc(row.cwe_name||row.name||row.product||row.component_type||dataset)}</p></div><button class="icon-button" data-close="detail-dialog" aria-label="Tutup detail">${icon('close')}</button></div><div class="dialog-body">${isDemo()?'<div class="inline-note">Entri contoh untuk demonstrasi antarmuka.</div>':''}${sections}<div class="section-label">Raw JSON</div><pre class="detail-json">${esc(typeof row.raw_json==='string'?row.raw_json:JSON.stringify(row.raw_json||(dataset==='attack'?Object.fromEntries(Object.entries(row).filter(([key])=>key!=='related_vulnerabilities')):row),null,2))}</pre></div>`;}
  let detailTicket=0;
  function showDetail(dataset,row,ticket){if(ticket!==detailTicket)return;$('#detail-content').innerHTML=detailsHTML(dataset,row);if(!$('#detail-dialog').open)$('#detail-dialog').showModal();}
  async function openDetail(dataset,id){const ticket=++detailTicket;try{let row;if(isDemo()){row=(samples[dataset]||[]).find(r=>dataset==='capec'?r.capec_id===id:r.id===Number(id));if(row&&dataset==='vulnerabilities')row={...row,cwes:[{cwe_id:row.cwe_id}],cpe_matches:[{criteria:'cpe:2.3:a:example:sample:*:*:*:*:*:*:*:*',sample:true}]};}else{row=await api('data/'+dataset+'/'+encodeURIComponent(id));}if(!row)throw new Error('Data tidak ditemukan.');showDetail(dataset,row,ticket);}catch(e){if(ticket===detailTicket)toast(e.message,true);}}
  async function openAttackDetail(attackId,{page=1,limit=10,mapping_kind='ALL',search=''}={}){
    if(isDemo()){const row=(samples.attack||[]).find(r=>r.attack_id===attackId);if(row)return openDetail('attack',row.id);toast('Teknik ini belum tersedia pada data contoh.');return;}
    const ticket=++detailTicket;
    try{const data=await api('attack/'+encodeURIComponent(attackId)+'/vulnerabilities?'+new URLSearchParams({page,limit,mapping_kind,search}));showDetail('attack',{...data.technique,attack_id:attackId,related_vulnerabilities:data},ticket);}catch(error){if(ticket===detailTicket)toast(error.message,true);}
  }
  async function connectionDialog(){let info=null;if(config.local){try{info=await api('config');}catch{}}openAction('Koneksi CTI',config.local?'Konfigurasi adapter pada komputer ini.':'Pratinjau antarmuka Web App.',`<div class="action-form">${config.local?`<div class="about-grid"><div><small class="text-muted">Instalasi CTI</small><strong class="mono">${esc(info?.vulndesk_root||'Belum tersedia')}</strong></div><div><small class="text-muted">Web server</small><strong class="mono">${esc(location.origin)}</strong></div></div><div class="field"><label for="mode-select">Mode data</label><select id="mode-select" class="input"><option value="live" ${!isDemo()?'selected':''}>Database & API lokal</option><option value="demo" ${isDemo()?'selected':''}>Data contoh</option></select></div><p class="metric-sub">Ubah direktori instalasi dan port modul melalui config.json, lalu restart server Web App. Kredensial database dibaca di server dari konfigurasi CTI.</p><div class="form-actions">${button('apply-mode','Terapkan','plug',true)}</div>`:`<div class="inline-note">Pratinjau ini memakai data contoh. Untuk data aktual, jalankan paket CTI Web pada komputer yang memiliki instalasi CTI dan MariaDB.</div><div><h3>Menjalankan versi lokal</h3><pre class="detail-json" style="margin-top:12px">pip install -r requirements-web.txt\npython server.py --vulndesk-root D:\\Vulndesk</pre><p class="metric-sub" style="margin-top:12px">Buka http://127.0.0.1:8801 setelah server berjalan.</p></div><div class="form-actions"><button class="btn" data-close="action-dialog">Tutup</button></div>`}</div>`);}
  async function syncDialog(){
    try {
      const sources=await sourceUI.acquisitionSources();
      if(!sources.length){toast('Daftarkan dan aktifkan API dengan adapter yang didukung sebelum membuat misi CTI.');navigate('sources');return;}
      const choices=sources.map(r=>`<option value="${esc(r.source_id)}">${esc(r.display_name)} · ${esc(r.source_id)}</option>`).join('');
      openAction('Misi akuisisi CTI',isDemo()?'Simulasi proposal sumber intelligence.':'Kirim proposal melalui orchestrator CTI dan otorisasi aptsGS.',`<form id="sync-form" class="action-form"><div class="inline-note">${isDemo()?'Mode contoh tidak membuat misi atau mengunduh data.':'Gunakan mission ID dan scope contract yang valid. Backend CTI menentukan task dan meminta keputusan GSS sebelum akuisisi sumber.'}</div><div class="field"><label for="sync-mission">Mission ID</label><input class="input mono" id="sync-mission" name="mission_id" required maxlength="100" placeholder="mission-…" value="${isDemo()?'mission-demo-001':''}"></div><div class="field"><label for="scope-id">Scope contract ID</label><input class="input mono" id="scope-id" name="scope_contract_id" required maxlength="160" placeholder="scope-…" value="${isDemo()?'scope-demo-001':''}"></div><div class="field"><label for="source-select">Sumber yang diusulkan</label><select id="source-select" class="input" name="source_id" required>${choices}</select></div><div class="form-actions"><button type="button" class="btn" data-close="action-dialog">Batal</button><button type="submit" class="btn primary">${isDemo()?'Simulasikan proposal':'Kirim proposal CTI'}</button></div></form>`);
    } catch(error){toast(error.message,true);}
  }
  function uploadDialog(){openAction('Impor dataset CSV','Tweet topics atau topics master.',`<form id="upload-form" class="action-form"><div class="field"><label for="dataset-type">Jenis dataset</label><select id="dataset-type" name="dataset_type" class="input"><option value="tweet_topics">Tweet topics</option><option value="topics_master">Topics master</option></select></div><div class="file-drop">Pilih CSV UTF-8, maksimum 5 MB.<input id="dataset-file" type="file" accept=".csv,text/csv" required aria-label="File CSV"></div><div class="metric-sub">Tweet topics: kolom Tweet dan Topic. Topics master: kolom Topic. ${isDemo()?'Data hanya diubah dalam sesi pratinjau ini.':'Import diteruskan ke DatasetService CTI.'}</div><div class="form-actions"><button type="button" class="btn" data-close="action-dialog">Batal</button><button class="btn primary" type="submit">${isDemo()?'Impor ke simulasi':'Impor dataset'}</button></div></form>`);}
  function deleteDialog(){openAction('Hapus dataset','Pilih jenis dan tanggal unggahan yang akan dihapus.',`<form id="delete-form" class="action-form"><div class="field"><label for="delete-type">Jenis dataset</label><select id="delete-type" name="dataset_type" class="input"><option value="tweet_topics">Tweet topics</option><option value="topics_master">Topics master</option></select></div><div class="field"><label for="delete-date">Tanggal unggahan</label><input id="delete-date" name="upload_date" type="date" class="input" required></div><div class="inline-note">${isDemo()?'Penghapusan hanya memengaruhi data contoh sesi ini.':'Semua baris dan salinan file unggahan untuk jenis serta tanggal tersebut akan dihapus dari CTI.'}</div><label class="checkbox-label"><input type="checkbox" name="confirm" required>Saya mengonfirmasi penghapusan dataset ini.</label><div class="form-actions"><button type="button" class="btn" data-close="action-dialog">Batal</button><button type="submit" class="btn danger">Hapus dataset</button></div></form>`);}
  function exportRows(){if(!state.rows.length)return toast('Tidak ada data pada halaman ini.');const keys=Object.keys(state.rows[0]).filter(k=>!['raw_json','config_json'].includes(k));const safeCSV=v=>{const t=v!=null&&typeof v==='object'?JSON.stringify(v):String(v??'');return '"'+(/^[\s]*[=+@-]/.test(t)?"'":'')+t.replace(/"/g,'""')+'"';};download('cti_'+currentDataset()+(isDemo()?'_contoh':'')+'.csv','\uFEFF'+[keys.map(safeCSV).join(','),...state.rows.map(r=>keys.map(k=>safeCSV(r[k])).join(','))].join('\r\n'),'text/csv;charset=utf-8');toast('Halaman saat ini diekspor ke CSV.');}
  function download(name,data,type){const url=URL.createObjectURL(new Blob([data],{type})),a=document.createElement('a');a.href=url;a.download=name;document.body.append(a);a.click();a.remove();setTimeout(()=>URL.revokeObjectURL(url),1000);}
  function parseCSV(text){const out=[];let row=[],value='',quoted=false;for(let i=0;i<text.length;i++){const c=text[i];if(c==='"'){if(quoted&&text[i+1]==='"'){value+='"';i++;}else quoted=!quoted;}else if(c===','&&!quoted){row.push(value);value='';}else if((c==='\n'||c==='\r')&&!quoted){if(c==='\r'&&text[i+1]==='\n')i++;row.push(value);if(row.some(v=>v.trim()))out.push(row);row=[];value='';}else value+=c;}if(quoted)throw new Error('CSV memiliki tanda kutip yang tidak lengkap.');if(value||row.length){row.push(value);out.push(row);}return out;}
  async function submitForm(form){const submit=$('[type="submit"]',form);submit.disabled=true;try{const fields=Object.fromEntries(new FormData(form));if(['source-form','source-delete-form'].includes(form.id)){await sourceUI.submit(form,fields);return;}if(form.id==='attack-relations-form'){await openAttackDetail(fields.attack_id,{page:1,limit:Number(fields.limit),mapping_kind:fields.mapping_kind,search:fields.search});}
    else if(form.id==='sync-form'){let result;if(isDemo()){result={mission_id:fields.mission_id,sample:true};toast('Proposal disimulasikan. Tidak ada akuisisi atau keputusan GSS.');}else{result=await api('missions/start',fields);toast('Proposal misi diterima CTI. Periksa status dan otorisasi GSS.');}state.missionId=result.mission_id||fields.mission_id;state.missionTab='status';$('#action-dialog').close();navigate('missions');}
    else if(form.id==='upload-form'){const file=$('#dataset-file').files[0];if(!file||file.size>5*1024*1024)throw new Error('Pilih CSV dengan ukuran maksimum 5 MB.');let n;if(isDemo()){const rows=parseCSV((await file.text()).replace(/^\uFEFF/,'')),head=rows.shift()?.map(v=>v.trim().toLowerCase().replace(/[^a-z0-9]/g,''));const tweetIndex=head?.findIndex(v=>['tweet','tweets','text'].includes(v)),topicIndex=head?.findIndex(v=>['topic','topics'].includes(v));if(!head||topicIndex<0||(fields.dataset_type==='tweet_topics'&&tweetIndex<0))throw new Error('CSV harus memiliki kolom Topic dan, untuk tweet topics, kolom Tweet.');const key=fields.dataset_type==='tweet_topics'?'tweets':'topics';const max=Math.max(0,...samples[key].map(r=>r.id));n=rows.length;rows.forEach((r,i)=>samples[key].push({id:max+i+1,tweet_text:r[tweetIndex]||'',topic_text:r[topicIndex]||'',file_name:file.name,uploaded_at:new Date().toISOString().slice(0,10)}));}else{const bytes=new Uint8Array(await file.arrayBuffer());let binary='';for(let i=0;i<bytes.length;i+=8192)binary+=String.fromCharCode(...bytes.subarray(i,i+8192));const result=await api('datasets/import',{dataset_type:fields.dataset_type,file_name:file.name,content_base64:btoa(binary)});n=result.rows_imported??result.row_count??result.inserted_count??'CSV';}state.page=1;$('#action-dialog').close();toast(`${n} baris diimpor${isDemo()?' ke simulasi':''}.`);await render();}
    else if(form.id==='delete-form'){if(isDemo()){const key=fields.dataset_type==='tweet_topics'?'tweets':'topics';samples[key]=samples[key].filter(r=>String(r.uploaded_at).slice(0,10)!==fields.upload_date);}else await api('datasets/delete',{dataset_type:fields.dataset_type,upload_date:fields.upload_date,confirm:true});state.page=1;$('#action-dialog').close();toast('Dataset untuk tanggal terpilih dihapus'+(isDemo()?' dalam simulasi.':'.'));await render();}
    else if(form.id==='mission-form'){state.missionId=$('#mission-id').value.trim();if(!/^[A-Za-z0-9_.:-]{1,160}$/.test(state.missionId))throw new Error('Gunakan Mission ID yang valid tanpa spasi.');await render();}
    else if(form.id==='filter-form'){if(fields.min&&fields.max&&Number(fields.min)>Number(fields.max))throw new Error('CVSS minimum tidak boleh melebihi maksimum.');Object.assign(state,{min:fields.min,max:fields.max,has_cpe:fields.has_cpe==='on',page:1});await render();}
  }catch(error){toast(error.message,true);}finally{if(submit.isConnected)submit.disabled=false;}}
  async function action(name){switch(name){case 'refresh':await render();break;case 'connection':await connectionDialog();break;case 'sync':await syncDialog();break;case 'source-add':await sourceUI.handleAction('add');break;case 'upload':uploadDialog();break;case 'delete-dataset':deleteDialog();break;case 'export':exportRows();break;case 'export-summary':download('cti_summary'+(isDemo()?'_contoh':'')+'.json',JSON.stringify({...state.loaded,sample:isDemo()},null,2),'application/json');break;case 'advanced':state.advanced=!state.advanced;await render();break;case 'reset-filters':Object.assign(state,{min:'',max:'',year:'',cwe:'',has_cpe:false,severity:'',search:'',page:1});await render();break;case 'apply-mode':state.mode=$('#mode-select').value;$('#action-dialog').close();await render();break;case 'diagnostics':try{const d=isDemo()?{sample:true,readiness_status:'SAMPLE',event_dispatcher_running:null,event_queue_depth:null,notice:'Tidak ada runtime yang diperiksa.'}:await api('diagnostics');$('#detail-content').innerHTML=detailsHTML('diagnostics',{name:'Diagnostik CTI',raw_json:d});$('#detail-dialog').showModal();}catch(e){toast(e.message,true);}break;case 'start-api':case 'stop-api':try{if(isDemo())toast((name==='start-api'?'Start':'Stop')+' API disimulasikan. Tidak ada proses yang dijalankan.');else{const d=await api('runtime/'+(name==='start-api'?'start':'stop'),{});toast(d.message);await render();}}catch(e){toast(e.message,true);}break;}}
  $('#detail-dialog').addEventListener('cancel',()=>{detailTicket++;});
  document.addEventListener('click',event=>{const target=event.target.closest('button, [data-navigate]');if(!target)return;if(target.dataset.attackRelations){void openAttackDetail(target.dataset.attackRelations,{page:Number(target.dataset.attackPage||1),limit:Number(target.dataset.attackLimit||10),mapping_kind:target.dataset.attackKind||'ALL',search:target.dataset.attackSearch||''});return;}if(target.dataset.cweFilter){pendingCwe=target.dataset.cweFilter;if(location.hash==='#vulnerabilities')void onRoute();else location.hash='vulnerabilities';return;}if(target.dataset.enrichmentDetail){void(async()=>{try{const d=await enrichmentDetail(target.dataset.enrichmentDetail);if(d){state.enrichmentDetail=d;state.enrichmentTab='evidence';void render({keep:true});}}catch(e){toast(e.message,true);}})();} else if(target.dataset.sourceAction)void sourceUI.handleAction(target.dataset.sourceAction,target.dataset.source);else if(target.dataset.close){if(target.dataset.close==='detail-dialog')detailTicket++;$('#'+target.dataset.close).close();}else if(target.dataset.action)void action(target.dataset.action);else if(target.dataset.navigate)navigate(target.dataset.navigate);else if(target.dataset.detail)void openDetail(target.dataset.dataset,target.dataset.detail);else if(target.dataset.page){state.page=Number(target.dataset.page);void render();}else if(target.dataset.sort){state.direction=state.sort===target.dataset.sort&&state.direction==='desc'?'asc':'desc';state.sort=target.dataset.sort;state.page=1;void render();}else if(target.dataset.tab){if(state.view==='missions')state.missionTab=target.dataset.tab;else if(state.view==='enrichment'){state.enrichmentTab=target.dataset.tab;void render({keep:true});return;}else state.tab=target.dataset.tab;state.page=1;state.search='';void render();}});
  document.addEventListener('submit',event=>{if(['attack-relations-form','source-form','source-delete-form','sync-form','upload-form','delete-form','mission-form','filter-form'].includes(event.target.id)){event.preventDefault();void submitForm(event.target);}});
  document.addEventListener('input',event=>{if(event.target.id==='search-input'){state.search=event.target.value;state.page=1;queueSearch();}else if(event.target.id==='filter-cwe'){state.cwe=event.target.value.trim();state.page=1;queueSearch('filter-cwe');}else if(event.target.id==='enrichment-mission'){state.enrichmentMission=event.target.value;state.page=1;clearTimeout(debounceTimer);debounceTimer=setTimeout(()=>render({keep:true}),400);}});
  document.addEventListener('keydown',event=>{if(event.key==='Enter'&&event.target.id==='search-input'){event.preventDefault();clearTimeout(debounceTimer);void render({keep:true,focusSearch:true});}else if(event.key==='Enter'&&event.target.id==='filter-cwe'){event.preventDefault();clearTimeout(debounceTimer);state.cwe=event.target.value.trim();state.page=1;void render({keep:true,focusSearch:true,focusInput:'filter-cwe'});}});
  document.addEventListener('change',async event=>{if(await sourceUI.changed(event.target))return;if(event.target.id==='filter-year'){clearTimeout(debounceTimer);++generation;catalogController?.abort();state[event.target.id==='filter-year'?'year':'cwe']=event.target.value.trim();state.page=1;await render();}else if(event.target.id==='severity-filter'){state.severity=event.target.value;state.page=1;await render();}else if(event.target.id==='page-size'){state.limit=Number(event.target.value);state.page=1;await render();}else if(event.target.dataset.toggle){const target=event.target,key=target.dataset.toggle,enabled=target.checked;target.disabled=true;try{if(isDemo()){samples.components.find(r=>r.service_key===key).enabled=enabled?1:0;toast('Konfigurasi komponen diubah dalam simulasi.');}else{await api('components/toggle',{service_key:key,enabled});toast('Konfigurasi enabled diperbarui.');}await render();}catch(e){target.checked=!enabled;toast(e.message,true);}finally{target.disabled=false;}}});
  $('#refresh-button').innerHTML=icon('refresh');$('#refresh-button').onclick=()=>render();$('#menu-button').innerHTML=icon('menu');$('#menu-button').onclick=()=>$('#sidebar').classList.toggle('open');$('#connection-button').innerHTML=icon('plug')+'<span>Koneksi & pengaturan</span>';$('#connection-button').onclick=connectionDialog;
  for(const dialog of document.querySelectorAll('dialog'))dialog.addEventListener('click',e=>{if(e.target===dialog){const r=dialog.getBoundingClientRect();if(e.clientX<r.left||e.clientX>r.right||e.clientY<r.top||e.clientY>r.bottom)dialog.close();}});
  window.addEventListener('hashchange',onRoute);onRoute();
  // WebMCP uses the same application state; it exposes navigation and read/search only.
  const context=document.modelContext,lifecycle=new AbortController();
  if(context?.registerTool){const register=t=>{try{Promise.resolve(context.registerTool(t,{signal:lifecycle.signal})).catch(()=>{});}catch{}};
    register({name:'navigate_vulndesk',title:'Buka halaman CTI',description:'Navigate to a CTI page. Does not launch missions or change backend configuration.',inputSchema:{type:'object',properties:{view:{type:'string',enum:pages.map(p=>p[0])}},required:['view'],additionalProperties:false},annotations:{readOnlyHint:false,untrustedContentHint:false},async execute(input){if(!input||Object.keys(input).some(k=>k!=='view')||!pages.some(p=>p[0]===input.view))throw new Error('Invalid view');history.replaceState(null,'','#'+input.view);await onRoute();return {view:state.view,mode:state.mode};}});
    register({name:'search_vulndesk_catalog',title:'Cari katalog CTI',description:'Search the current CTI catalog and return the visible page. Does not run external acquisition.',inputSchema:{type:'object',properties:{query:{type:'string',maxLength:200}},required:['query'],additionalProperties:false},annotations:{readOnlyHint:false,untrustedContentHint:true},async execute(input){if(!input||Object.keys(input).some(k=>k!=='query')||typeof input.query!=='string'||input.query.length>200||!catalogs[currentDataset()]&&state.view!=='vulnerabilities')throw new Error('Open a catalog and supply a valid query');state.search=input.query;state.page=1;await render();return {view:state.view,sample:isDemo(),total:state.total,items:state.rows.map(r=>Object.fromEntries(Object.entries(r).filter(([k])=>k!=='raw_json')))};}});
    register({name:'read_vulndesk_view',title:'Baca halaman CTI',description:'Read the current view, dataset mode, and visible records.',inputSchema:{type:'object',properties:{},additionalProperties:false},annotations:{readOnlyHint:true,untrustedContentHint:true},execute(input){if(!input||Object.keys(input).length)throw new Error('No arguments expected');return {view:state.view,mode:state.mode,sample:isDemo(),search:state.search,total:state.total,rows:state.rows.map(r=>Object.fromEntries(Object.entries(r).filter(([k])=>k!=='raw_json')))};}});
    window.addEventListener('pagehide',()=>lifecycle.abort(),{once:true});
  }
})();
